  /* Slab casting status for map colouring (mirrors column status): none/todo/wip/done */
  elemDoneInMonth(lv,zmk,types,m){const z=(this.DATA.levels[lv]?this.DATA.levels[lv].zones:[]).find(x=>(x.mk||x.lid)===zmk);if(!z)return null;let n=0;types.forEach(tp=>{this._zoneElemList(z,tp).forEach(x=>{const id=(typeof x==='string')?x:x.id;const k=this.ekey(lv,z,tp,id);if(this.elemStatus(k)==='done'){const d=this.elemDate(k)||this.todayISOStr();if(this.dateToActMonth(d)===m)n++;}});});return n>0?n:null;}

  /* ---------- cloud sync (Supabase accounts + per-record sync) ---------- */
  zoneCat(lv,zoneMk){
    if(!this._zoneCat){ this._zoneCat={}; this.DATA.order.forEach(l=>this.DATA.levels[l].zones.forEach(z=>{this._zoneCat[l+'||'+this.zid(z)]=z.cat||'NB';})); }
    let c=this._zoneCat[lv+'||'+zoneMk]; if(c==null)c=this._zoneCat[lv+'||_'+zoneMk]; return c;
  }
  // admin: everything. normal user: only zones whose area (EB/NB/MA) is in allowed_scopes.
  rwsScopeOk(lv,zoneMk){
    const u=this._rwsUser; if(!u)return false; if(u.role==='admin')return true;
    const areas=Array.isArray(u.allowed_scopes)?u.allowed_scopes:[];
    return areas.indexOf(this.zoneCat(lv,zoneMk))>=0;
  }
  rwsCanEditElement(key){
    const u=this._rwsUser; if(!u)return false; if(u.role==='admin')return true;
    const parts=key.split('||'); if(parts.length!==4)return false;
    const lv=parts[0],zmk=parts[1],etype=parts[2];
    return this.rwsScopeOk(lv,zmk);
  }
  rwsIsAdmin(){return !window.__RWS_LOCKED_VIEW && !!this._rwsUser && this._rwsUser.role==='admin';}   /* 只读快照里永远不是 admin → 隐藏并禁止一切编辑 */
  rwsHasScope(code){const u=this._rwsUser;if(!u)return false;if(u.role==='admin')return true;const a=Array.isArray(u.allowed_scopes)?u.allowed_scopes:[];return a.indexOf(code)>=0;}
  /* 评论权限: 必须有 CMT。范围跟随被授权的区域 —— 勾了区域就只能评论那些区; 只勾 CMT(没勾任何区)= 全区可评 */
  rwsCanSnapshot(){const u=this._rwsUser;if(!u)return false;if(u.role==='admin')return true;const a=Array.isArray(u.allowed_scopes)?u.allowed_scopes:[];return a.indexOf('HIST')>=0;}   /* 谁能看历史快照: admin 或有 HIST 权限 */
  rwsCanComment(lv,zmk){const u=this._rwsUser;if(!u)return false;if(u.role==='admin')return true;const a=Array.isArray(u.allowed_scopes)?u.allowed_scopes:[];if(a.indexOf('CMT')<0)return false;const AREAS=['EB','NB','MA','M28_OTHER'];const hasArea=AREAS.some(c=>a.indexOf(c)>=0);if(!hasArea)return true;return a.indexOf(this.zoneCat(lv,zmk))>=0;}
